input.sparql:
SELECT ?zone ?zs ?zoneLabel WHERE {
  ?zone a brick:HVAC_Zone ; brick:hasLabel ?zoneLabel .
  FILTER (?zoneLabel = "DataCenter_bot_ZN_6" || ?zone = "DataCenter_bot_ZN_6")
} LIMIT 20

SELECT ?s ?type WHERE {
  ?zone_uri a brick:HVAC_Zone .
  ?zone_uri rdfs:label "DataCenter_bot_ZN_6" .
  ?s ?p ?zone_uri .
  ?s a ?type .
} LIMIT 80

SELECT ?s ?type WHERE {
  ?zone_uri a brick:HVAC_Zone .
  ?zone_uri rdfs:label "DataCenter_bot_ZN_6" .
  ?zone_uri ?p ?s .
  ?s a ?type .
} LIMIT 80

SELECT DISTINCT ?p WHERE {
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  ?zone_uri a brick:HVAC_Zone .
  ?zone_uri rdfs:label "DataCenter_bot_ZN_6" .
  ?zone_uri ?rel ?sensor .
}
